"""Publish matched saved-model review evidence, without inferring art acceptance."""
from pathlib import Path
import hashlib,json,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-torso-r5'
row=json.loads((OUT/'refinement-metrics.json').read_text(encoding='utf-8'));ID=row['id']
checks=json.loads((OUT/'verification.json').read_text(encoding='utf-8'))
contacts=json.loads((OUT/'attachment-verification.json').read_text(encoding='utf-8'))
assert checks['source_sha256']==hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest()
assert checks['triangles']==row['triangles']<=1800 and contacts['result']=='PASS'
assert contacts['endpoints']==40 and contacts['sampled_poses']==35
concept=json.loads((OUT/'concept-pass.json').read_text(encoding='utf-8'))
concept.update(scope='torso and neck interpretation correction; not final surface detail',anatomy='metal ribs wrap around the crystal core above and below a solid V-shaped stone cross-chest band; upper stone collarbone supports separate metal neck ribs into the retained head',remaining='user torso review; crown and shoulder silhouette; individualized weathering, stone fractures and corroded metal textures; native animation/performance acceptance')
(OUT/'concept-pass.json').write_text(json.dumps(concept,indent=2)+'\n',encoding='utf-8')
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — ribbed torso r5</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}}}</style>
<h1>Rift Titan — ribbed torso r5</h1>
<p>The concept torso has numerous swept metal ribs around the crystal core, a stone band bent into a solid downward V, an upper stone collarbone, and separate metal neck ribs joining that collar to the head. This revision replaces the previous hoops and four-brace basket with those groups. Six front ribs seat into the central band; eight deeper ribs continue below it into the lower cage. Six neck ribs connect the collar and head. Rib sections follow the bends without roll flips, with a rough dark surface.</p>
<p><strong>{row['triangles']:,} triangles · {row['ratio']:.3f}× native Stone Golem · soft cap 1,800</strong>. One mesh/material and four 512px maps. Forty rib roots pass 35 sampled poses across seven retained actions. This remains a candidate for visual review; texture and stone fracture detail still need refinement.</p>
<h2>Torso close-up</h2><div class="pair"><figure><img src="concept-v-band-detail.png" alt="User-supplied concept close-up of the stone V band and surrounding ribs"><figcaption>Concept — solid stone band bends down at the central V, with ribs behind and below it</figcaption></figure><figure><img src="{ID}--detail.png" alt="Saved r5 torso and neck"><figcaption>Current saved geometry — upper collar, ribbed neck, central V band and lower rib cage</figcaption></figure></div>
<h2>Before and after — matched views</h2><div><button data-view="three-quarter">Surface</button><button data-view="clay">Clay</button><button data-view="front">Front</button><button data-view="side">Side</button><button data-view="detail">Torso</button></div><div class="pair"><figure><img id="before" src="../rift-titan-strata-r4/underworld-boss-rift-titan-strata-r4--three-quarter.png" alt="Preserved r4 model"><figcaption>Previous r4 — hoops and four diagonal braces</figcaption></figure><figure><img id="after" src="{ID}--three-quarter.png" alt="Saved r5 model"><figcaption>Current r5 — metal torso ribs, V stone band, collarbone and ribbed neck</figcaption></figure></div>
<h2>Concept front and side</h2><div class="pair"><figure><img src="concept-front.png" alt="User-supplied front concept view"><figcaption>Concept front — collarbone, stone V band and metal ribs</figcaption></figure><figure><img src="concept-side.png" alt="User-supplied side concept view"><figcaption>Concept side — rib cage depth and taper beneath the stone band</figcaption></figure></div>
<h2>Adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Rift Titan concept front, side and torso detail">
<h2>Native donor reference</h2><img style="max-width:900px" src="../../2026-10-04/detail-r2/donor-StoneGolem--three-quarter.png" alt="Extracted native Stone Golem quality and cost reference">
<p>The torso and neck were revised; the r4 limbs, shoulders, crown, rig and actions remain. Stone weathering, individualized fracture detail and the overall silhouette are still unfinished. Native admission and live performance are pending. The rolling tally remains one adequately reworked boss of six.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--attack.png">Retained attack pose</a> · <a href="verification.json">Geometry and export checks</a> · <a href="attachment-verification.json">Rib contact checks</a> · <a href="torso-authoring.json">Torso construction</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='../rift-titan-strata-r4/underworld-boss-rift-titan-strata-r4--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_ribbed_torso.py','tools/refine-rift-titan-torso-r5.py','tools/review-rift-titan-torso-r5.py','tools/verify-rift-titan-torso-r5.py','tools/publish-rift-titan-torso-r5.py',row['source'],'docs/art/creature-concepts/2026-10-03/the-rift-titan.png']+[p.relative_to(ROOT).as_posix() for p in sorted(OUT.glob('concept-*.png'))]
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},acceptance='unaccepted torso candidate; tally remains 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
print('VERIFIED r5 review links, cap and saved source hash')
